rep(p,"        // ------------------------------------------------------------ визуал\n",`        // NB121: pack actual, simultaneously shown floor circles around actual
        // work rings. Hidden/SheetOnly records are not physical floor geometry.
        // Called on visibility changes and when a new work ring is built.
        public const float FloorGap = 0.5f;
        static readonly List<BuyCircle> _floorLive = new List<BuyCircle>(32);
        public static float WorkRingRadius(Pitt.Production.Workbench b) =>
            b.CircleRadius * (b.Zone == HallProdDefs.Zone ? 1f : 1.1f);

        public static bool FloorReachable(Vector3 at, float radius)
        {
            var size = HallGeo.SizeNow * 0.5f;
            if (Mathf.Abs(at.x) + radius + 0.15f > size.x || Mathf.Abs(at.z) + radius + 0.15f > size.y) return false;
            if (Game.Pit != null && Ext.FlatDist(at, Game.Pit.Center) < Game.Pit.Radius + radius + 0.35f) return false;
            const float clearance = 0.42f; // same capsule as BotGrid, no products/UI/triggers
            return !Physics.CheckCapsule(at.WithY(clearance + 0.06f), at.WithY(1.1f), clearance,
                (1 << Layers.Default) | (1 << Layers.PlayerOnly), QueryTriggerInteraction.Ignore);
        }

        public static int ReflowFloor()
        {
            if (!OnePitBalance.FlowV3 || Game.State == null || !Game.State.Hall) return 0;
            _floorLive.Clear();
            foreach (var src in new[] { All, LockedAll })
                foreach (var c in src) if (c && c.OnFloor && !_floorLive.Contains(c)) _floorLive.Add(c);
            _floorLive.Sort((a, b) => a.Seq.CompareTo(b.Seq));
            var rings = UnityEngine.Object.FindObjectsByType<Pitt.Production.Workbench>(
                FindObjectsInactive.Exclude, FindObjectsSortMode.None);
            int moved = 0;
            for (int i = 0; i < _floorLive.Count; i++)
            {
                var c = _floorLive[i];
                var at = c.transform.position;
                if (FitsFloor(c, at, i, rings)) continue;
                bool found = false;
                // Prefer the specified slot, then the closest reachable alternative.
                for (int step = 0; step <= 16 && !found; step++)
                {
                    int count = step == 0 ? 1 : 32;
                    for (int k = 0; k < count; k++)
                    {
                        float a = k * Mathf.PI * 2f / count;
                        var q = c._floorHome + new Vector3(Mathf.Cos(a), 0f, Mathf.Sin(a)) * (step * 0.25f);
                        // Motor1 must stay on the right of bench1, including old partial saves.
                        if (c.Id == HallProdDefs.Motor1Id && q.x < HallRowDefs.X(0) + 2.5f) continue;
                        if (!FitsFloor(c, q, i, rings)) continue;
                        c.transform.position = q;
                        c._payT = c._inT = 0f;
                        c._plateInit = false;
                        var hero = Game.Player;
                        c._armed = hero == null || Ext.FlatDist(hero.Position, q) > c.Radius + ArmOut;
                        moved++;
                        found = true;
                        break;
                    }
                }
                if (!found) Debug.LogError("[PITT] ERR [onepit] floor has no reachable separated slot id=" + c.Id);
            }
            return moved;
        }

        static bool FitsFloor(BuyCircle c, Vector3 at, int before, Pitt.Production.Workbench[] rings)
        {
            if (!FloorReachable(at, c.Radius)) return false;
            for (int k = 0; k < before; k++)
            {
                var o = _floorLive[k];
                if (Ext.FlatDist(at, o.transform.position) < c.Radius + o.Radius + FloorGap + 0.01f) return false;
            }
            foreach (var b in rings)
            {
                if (!b || !b.isActiveAndEnabled || !b.HasCircle || !b.Ring.gameObject.activeInHierarchy) continue;
                if (Ext.FlatDist(at, b.CircleCenter) < c.Radius + WorkRingRadius(b) + FloorGap + 0.01f) return false;
            }
            return true;
        }

        // --…

